import { discoveredStylesSources, droneSources, partyHouseSources, redAppleOrchardSources, safeCodesExtraSources } from "@/src/data/launch/batch17-sources";

export type QuickGuideLink = {
  href: string;
  title: string;
  line?: string;
  image?: string;
  imageAlt?: string;
  kind?: string;
};

export type QuickGuide = {
  slug: string;
  /** SEO title, without the site name. */
  title: string;
  /** Short page heading. */
  heading: string;
  /** Meta description. Starts or ends with "Unofficial". */
  description: string;
  keywords: string[];
  /** Existing confirmed site image or official Rockstar image. Blank card when missing. */
  image?: string;
  imageAlt?: string;
  /** Icon kind for cards. */
  kind: string;
  /** 2 to 4 short plain sentences that answer the question. */
  answer: string[];
  /** Timing or missable-content warning, shown as a callout under the title. */
  notice?: string;
  price?: string;
  facts?: { label: string; value: string }[];
  /** Questions for FAQ schema. Answers repeat the page text. */
  faqs: { question: string; answer: string }[];
  related: QuickGuideLink[];
  /** Short source labels. Shown only when SHOW_PUBLIC_SOURCES is on. */
  sources?: readonly { label: string; href?: string }[];
};

